<script setup lang="ts">
import { onBeforeUnmount, onMounted, ref } from 'vue'
import { useRoute } from 'vue-router'
import WorkspaceShell from '../components/WorkspaceShell.vue'
import { publicApi, durationLabel } from '../api/public'
import type { PublicVideo } from '../api/public'
import type { SignedMedia } from '../api/creator'
import { formatTime } from '../api/creator'
import { useStudioError } from '../composables/useStudioError'
const id = String(useRoute().params.id); const explain = useStudioError(); const video = ref<PublicVideo>(); const media = ref<SignedMedia>(); const player = ref<HTMLVideoElement>(); const loading = ref(false); const signing = ref(false); const favoriteBusy = ref(false); const favorited = ref<boolean>(); const error = ref(''); const mediaError = ref(''); const favoriteError = ref(''); const notice = ref(''); let activeRequest: AbortController | undefined; let mediaRequest: AbortController | undefined; const lifetime = new AbortController()
function clearMedia() { player.value?.pause(); player.value?.removeAttribute('src'); player.value?.load(); media.value = undefined }
async function load() { activeRequest?.abort(); mediaRequest?.abort(); signing.value = false; clearMedia(); const controller = new AbortController(); activeRequest = controller; loading.value = true; error.value = ''; video.value = undefined; try { const result = await publicApi.get(id, controller.signal); if (!controller.signal.aborted) video.value = result } catch (failure) { if (!controller.signal.aborted) error.value = explain(failure) } finally { if (!controller.signal.aborted) loading.value = false } }
async function play() { if (!video.value || signing.value || loading.value) return; mediaRequest?.abort(); const controller = new AbortController(); mediaRequest = controller; signing.value = true; mediaError.value = ''; clearMedia(); try { const result = await publicApi.media(id, 'SOURCE', controller.signal); if (!controller.signal.aborted) media.value = result } catch (failure) { if (!controller.signal.aborted) mediaError.value = explain(failure) } finally { if (!controller.signal.aborted) signing.value = false } }
async function favoriteState() { favoriteBusy.value = true; favoriteError.value = ''; try { const result = await publicApi.favoriteState(id, lifetime.signal); if (!lifetime.signal.aborted) favorited.value = result.favorited } catch (failure) { if (!lifetime.signal.aborted) { favorited.value = undefined; favoriteError.value = explain(failure) } } finally { if (!lifetime.signal.aborted) favoriteBusy.value = false } }
async function toggleFavorite() { if (favoriteBusy.value || favorited.value === undefined) return; const add = !favorited.value; favoriteBusy.value = true; favoriteError.value = ''; notice.value = ''; try { await publicApi.favorite(id, add); if (!lifetime.signal.aborted) { favorited.value = add; notice.value = add ? '已加入收藏。' : '已取消收藏。' } } catch (failure) { if (!lifetime.signal.aborted) { favoriteError.value = `${explain(failure)}。正在核对收藏状态。`; favorited.value = undefined; await favoriteState() } } finally { if (!lifetime.signal.aborted) favoriteBusy.value = false } }
onMounted(() => { if (/^[1-9]\d{0,18}$/.test(id)) { void load(); void favoriteState() } else error.value = '作品编号无效' }); onBeforeUnmount(() => { lifetime.abort(); activeRequest?.abort(); mediaRequest?.abort(); clearMedia() })
</script>
<template><WorkspaceShell><RouterLink class="back-link" to="/">← 发现作品</RouterLink><el-alert v-if="error" :title="error" type="error" :closable="false" role="alert" /><p v-if="loading" class="empty-state" role="status">正在读取作品…</p><el-button v-if="error" @click="load">重新读取</el-button><template v-if="video"><section class="watch-screen" aria-label="视频播放器"><video v-if="media" ref="player" :src="media.url" controls playsinline preload="metadata" @error="mediaError = '视频无法加载或链接已过期，请重新获取播放地址。'" /><div v-else class="watch-prompt"><span>{{ durationLabel(video.durationMillis) }}</span><p>准备观看《{{ video.title }}》</p><el-button :loading="signing" @click="play">加载视频</el-button></div></section><el-alert v-if="mediaError" :title="mediaError" type="error" :closable="false" role="alert" /><div class="watch-toolbar"><span>{{ video.categoryName }} · {{ video.width }} × {{ video.height }}</span><el-button :loading="signing" @click="play">重新获取播放地址</el-button></div><div class="watch-heading"><div><h1>{{ video.title }}</h1><p class="muted">{{ video.authorName }} · 发布于 {{ formatTime(video.publishedAt) }}</p></div><el-button :loading="favoriteBusy" :disabled="favorited === undefined" @click="toggleFavorite">{{ favorited ? '取消收藏' : '收藏作品' }}</el-button></div><el-alert v-if="favoriteError" :title="favoriteError" type="error" :closable="false" role="alert" /><el-button v-if="favorited === undefined" :disabled="favoriteBusy" @click="favoriteState">查询收藏状态</el-button><p v-if="notice" role="status" class="muted">{{ notice }}</p><p class="video-description">{{ video.description || '作者未填写简介。' }}</p><p v-if="media" class="muted">播放地址到期：{{ formatTime(media.expiresAt) }}。过期后可重新获取。</p></template></WorkspaceShell></template>
